function hasPermission(permission){ return rolePermissions[state.role]?.includes(permission); }
function formatType(type){ return ({research:'Research',ic:'Investment Committee',clients:'Client Reports',compliance:'Compliance',valuations:'Valuations',legal:'Mandates & Legal'})[type] || type; }
function statusClass(status){ const s=status.toLowerCase(); if(s.includes('approved')||s.includes('published')||s.includes('current')||s.includes('within')||s.includes('filled')||s.includes('matched')) return 'green'; if(s.includes('await')||s.includes('review')||s.includes('routing')||s.includes('partial')||s.includes('draft')||s.includes('amber')) return 'amber'; if(s.includes('fail')||s.includes('restricted')||s.includes('high')||s.includes('red')) return 'red'; return ''; }

