function renderOrders(){
  const statusFilter=$('#orderStatusFilter')?.value || 'all';
  const marketFilter=$('#orderMarketFilter')?.value || 'all';
  const sideFilter=$('#orderSideFilter')?.value || 'all';
  const query=($('#orderSearch')?.value||'').trim().toLowerCase();
  const filtered=orders.filter(o=>(statusFilter==='all'||o.status===statusFilter)&&(marketFilter==='all'||o.market===marketFilter)&&(sideFilter==='all'||o.side===sideFilter)&&(!query||`${o.id} ${o.security} ${o.name||''} ${o.portfolio} ${o.broker}`.toLowerCase().includes(query)));
  const rowHtml=o=>`<tr data-order="${o.id}"><td><strong>${o.id}</strong><small>${o.time} CAT</small></td><td><strong>${o.security}</strong><small>${o.market} · ${o.name||''}</small></td><td class="${o.side==='Buy'?'side-buy':'side-sell'}"><strong>${o.side}</strong></td><td><strong>${o.qty}</strong><small>${o.notional||'—'}</small></td><td><div class="execution-cell"><div><strong>${o.fill||0}% filled</strong><span>${o.avg||'—'}</span></div><i><u style="width:${o.fill||0}%"></u></i><small>${o.filledQty||'0'} · limit ${o.limit}</small></div></td><td><strong>${o.broker}</strong><small>${o.route||''}</small></td><td>${o.portfolio}</td><td><span class="tag ${o.control==='Amber'?'amber':o.control==='Blocked'?'red':'green'}">${o.control||'Within'}</span><small>${o.risk||''}</small></td><td><span class="status-dot ${statusClass(o.status)||'blue'}"></span><strong>${o.status}</strong><small>${o.settlement||''}</small></td><td>${o.age||'—'}</td><td><button class="row-action">Open</button></td></tr>`;
  const body=$('#orderRows'); if(body)body.innerHTML=filtered.map(rowHtml).join('');
  const count=$('#orderFilterCount'); if(count)count.textContent=`${filtered.length} order${filtered.length===1?'':'s'}`;
  const live=orders.filter(o=>!['Filled','Cancelled'].includes(o.status));
  const awaiting=orders.filter(o=>o.status==='Awaiting approval');
  const filledWeighted=orders.reduce((a,o)=>a+(o.fill||0),0)/Math.max(1,orders.length);
  if($('#orderLiveCount'))$('#orderLiveCount').textContent=`${live.length} orders`;
  if($('#orderAwaitingCount'))$('#orderAwaitingCount').textContent=awaiting.length;
  if($('#approvalQueueCount'))$('#approvalQueueCount').textContent=awaiting.length;
  if($('#approvalQueueTabCount'))$('#approvalQueueTabCount').textContent=awaiting.length;
  if($('#weightedFillKpi'))$('#weightedFillKpi').textContent=`${filledWeighted.toFixed(1)}%`;
  const approvalQueue=$('#orderApprovalQueue');
  if(approvalQueue) approvalQueue.innerHTML=(awaiting.length?awaiting:orders.filter(o=>o.status==='Approved').slice(0,2)).map(o=>`<button data-order="${o.id}"><span class="queue-severity ${o.control==='Amber'?'amber':'green'}"></span><div><strong>${o.security} · ${o.side} ${o.qty}</strong><small>${o.portfolio} · ${o.notional} · ${o.risk}</small></div><em>${o.status==='Awaiting approval'?'Decision required':'Approved'}</em></button>`).join('');
  const executionQueue=$('#orderExecutionQueue');
  const working=orders.filter(o=>['Routing','Partially filled','Approved'].includes(o.status)).slice(0,3);
  if(executionQueue) executionQueue.innerHTML=working.map(o=>`<button data-order="${o.id}"><div class="execution-queue-top"><span><strong>${o.security}</strong><small>${o.broker} · ${o.status}</small></span><b>${o.fill||0}%</b></div><i><u style="width:${o.fill||0}%"></u></i><div class="execution-queue-meta"><span>${o.filledQty||'0'} / ${o.qty}</span><span>${o.slippage||'No fills yet'}</span><span>${o.settlement}</span></div></button>`).join('');
  const cmd=$('#commandOrderRows'); if(cmd)cmd.innerHTML=orders.slice(0,5).map(o=>`<tr data-order="${o.id}"><td><strong>${o.id.replace('ORD-260826-','…')}</strong></td><td>${o.market}</td><td><strong>${o.security}</strong></td><td class="${o.side==='Buy'?'side-buy':'side-sell'}">${o.side}</td><td>${o.qty}</td><td>${o.limit}</td><td>${o.portfolio}</td><td><span class="tag ${statusClass(o.status)}">${o.status}</span></td></tr>`).join('');
  $$('[data-order]').forEach(row=>row.onclick=e=>{if(e.target.closest('[data-order-action]'))return;openOrderDrawer(orders.find(o=>o.id===row.dataset.order));});
}
