function openResearchCase(r){
  const thesis={
    'INN.ZW':'Margin resilience, pricing power and distribution growth support earnings upgrades. Upside remains attractive after liquidity and issuer-headroom checks.',
    'ZIM.VX':'Commodity upside remains balanced by basket-price volatility, capex intensity and VFEX liquidity. Hold pending refreshed operating assumptions.',
    'DLTA.ZW':'Volume growth and gross-margin resilience remain supportive, but issuer concentration is close enough to the internal limit to constrain position sizing.',
    'FBC.ZW':'The fundamental case remains defensible, but group-level economic exposure has reached the internal risk budget; position reduction protects headroom.',
    'T-BILL-91D':'Short-duration yield supports liquidity while limiting rate sensitivity. Allocation remains dependent on cash forecasts and auction clearing levels.'
  }[r.ticker]||'Approved investment thesis and evidence are retained in the research record.';
  const risks={
    'INN.ZW':['Consumer demand slowdown','Margin compression','Valuation multiple contraction'],
    'ZIM.VX':['Metal-price weakness','Capex overrun','Thin secondary-market liquidity'],
    'DLTA.ZW':['Issuer concentration','Input-cost pressure','Volume sensitivity'],
    'FBC.ZW':['Group concentration','Credit-cycle deterioration','Regulatory capital pressure'],
    'T-BILL-91D':['Reinvestment risk','Auction repricing','Liquidity scheduling']
  }[r.ticker]||['Market risk','Liquidity risk','Execution risk'];
  openDrawer({eyebrow:'RESEARCH 360',title:`${r.ticker} · ${r.name}`,subtitle:`${r.view} · Conviction ${r.score} · Analyst ${r.owner}`,body:`<div class="drawer-summary"><div><span>Approved view</span><strong>${r.view}</strong><small>Current recommendation</small></div><div><span>Target / yield</span><strong>${r.target}</strong><small>Current approved model</small></div><div><span>Next review</span><strong>${r.review}</strong><small>Freshness policy monitored</small></div></div><section class="detail-section"><h3>Investment thesis</h3><p>${thesis}</p></section><section class="detail-section"><h3>Decision evidence</h3><div class="detail-grid compact"><div class="detail-field"><span>Model version</span><strong>v6 · approved</strong></div><div class="detail-field"><span>Primary valuation</span><strong>DCF + relative multiples</strong></div><div class="detail-field"><span>Evidence pack</span><strong>7 controlled files</strong></div><div class="detail-field"><span>Last material change</span><strong>Results / guidance refresh</strong></div></div></section><section class="detail-section"><h3>Key risks & invalidation tests</h3><ul>${risks.map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="detail-section"><h3>Committee / portfolio consequences</h3><p>Any trade created from this recommendation must re-run cash, liquidity, issuer concentration, mandate and counterparty controls. The order retains this research record as decision evidence.</p></section><div class="form-actions"><button class="btn secondary" onclick="navigate('vault');closeDrawer()">Open evidence</button><button class="btn secondary" onclick="navigate('risk');closeDrawer()">Check risk impact</button><button class="btn primary" onclick="navigate('orders');closeDrawer()">Create order</button></div>`});
}

function renderPretrade(){
  const qty=Math.max(0,Number($('#orderQty')?.value||0)), price=Math.max(0,Number($('#orderPrice')?.value||0));
  const ccy=$('#orderCurrency')?.value||'ZWG', side=$('#orderSide')?.value||'Buy', market=$('#orderMarket')?.value||'ZSE';
  const consideration=qty*price;
  const cashBefore=ccy==='USD'?2110000:34500000, reservations=ccy==='USD'?184000:1850000;
  const eligibleBefore=cashBefore-reservations;
  const diagnosticAfter=side==='Buy'?eligibleBefore-consideration:eligibleBefore;
  const cashAfter=Math.max(0,diagnosticAfter);
  const participation=qty/1860000*100;
  const participationLimit=Number($('#orderParticipation')?.value||15);
  const issuerMove=(qty/250000)*0.62*(side==='Buy'?1:-1);
  const issuer=Math.max(0,9.10+issuerMove);
  const equity=37.20+(qty/250000)*0.65*(side==='Buy'?1:-1);
  const feeEstimate=consideration*0.0025;
  const fmt=(v,compact=false)=>compact?v.toLocaleString(undefined,{notation:'compact',maximumFractionDigits:2}):v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
  if($('#orderConsideration'))$('#orderConsideration').textContent=`${ccy} ${fmt(consideration)}`;
  if($('#orderFeeEstimate'))$('#orderFeeEstimate').textContent=`Est. fees ${ccy} ${fmt(feeEstimate)}`;
  if($('#cashAfter'))$('#cashAfter').textContent=`${ccy} ${fmt(cashAfter,true)}`;
  if($('#postWeight'))$('#postWeight').textContent=`${issuer.toFixed(2)}%`;
  if($('#issuerHeadroom'))$('#issuerHeadroom').textContent=`${Math.max(0,10-issuer).toFixed(2)}% headroom`;
  if($('#advParticipation'))$('#advParticipation').textContent=`${participation.toFixed(1)}%`;
  if($('#sideAdv'))$('#sideAdv').textContent=`${participation.toFixed(1)}%`;
  if($('#liquidityReadout'))$('#liquidityReadout').textContent=participation>participationLimit?`Above ${participationLimit}% route policy`:`Within ${participationLimit}% route policy`;
  if($('#sideIssuerUsage'))$('#sideIssuerUsage').textContent=`${issuer.toFixed(2)} / 10.00%`;
  if($('#sideIssuerHeadroom'))$('#sideIssuerHeadroom').textContent=`${Math.max(0,10-issuer).toFixed(2)}% remaining`;
  if($('#sideIssuerBar'))$('#sideIssuerBar').style.width=`${Math.min(100,issuer*10)}%`;
  if($('#sideCashUsage'))$('#sideCashUsage').textContent=`${ccy} ${fmt(cashAfter,true)}`;
  if($('#sideOrderValue'))$('#sideOrderValue').textContent=`${ccy} ${fmt(consideration,true)}`;
  if($('#sideSettlementCcy'))$('#sideSettlementCcy').textContent=ccy;
  const ask=11.82;
  if($('#limitVsAsk'))$('#limitVsAsk').textContent=(market==='ZSE'&&price?`${((price/ask-1)*100).toFixed(2)}%`:'n/a');
  const impact=Math.min(100,Math.max(8,participation/Math.max(1,participationLimit)*60));
  if($('#impactBar'))$('#impactBar').style.width=`${impact}%`;
  if($('#impactEstimate'))$('#impactEstimate').textContent=participation>participationLimit?'Elevated':participation>participationLimit*.7?'Moderate':'Low';
  const duplicate=orders.some(o=>!['Filled','Cancelled'].includes(o.status)&&o.security===$('#orderTicker')?.value&&o.side===side&&o.portfolio===$('#orderPortfolio')?.value);
  const checks=[
    {status:'pass',title:'Ownership & account scope',detail:'Portfolio, mandate, currency and dealing authority are compatible.'},
    {status:side==='Buy'?(diagnosticAfter<0?'fail':diagnosticAfter<cashBefore*.08?'warn':'pass'):'pass',title:side==='Buy'?'Available cash':'Available securities',detail:side==='Buy'?`${ccy} ${fmt(eligibleBefore,true)} eligible before order · ${ccy} ${fmt(diagnosticAfter,true)} diagnostic after`:`Position availability covers proposed sale quantity.`},
    {status:issuer>10?'fail':issuer>9?'warn':'pass',title:'Single issuer limit',detail:`${issuer.toFixed(2)}% post-trade · hard limit 10.00% · ${Math.max(0,10-issuer).toFixed(2)}% headroom`},
    {status:equity>40?'fail':equity>38?'warn':'pass',title:'Asset-class mandate',detail:`${equity.toFixed(2)}% equities post-trade · limit 40.00%`},
    {status:participation>participationLimit?'fail':participation>participationLimit*.8?'warn':'pass',title:'Liquidity / market impact',detail:`Order is ${participation.toFixed(1)}% of 20-day ADV · route policy ${participationLimit}%`},
    {status:'pass',title:'Security eligibility',detail:`${$('#orderTicker')?.value||'Security'} is on the approved investment universe.`},
    {status:'pass',title:'Counterparty & custody',detail:`${$('#orderBroker')?.value||'Broker'} and ${$('#orderCustodian')?.value||'custodian'} are active and approved.`},
    {status:market==='VFEX'&&$('#orderBroker')?.value==='IH Securities'?'warn':'pass',title:'Settlement & SSI readiness',detail:market==='VFEX'?'VFEX settlement instruction requires final SSI confirmation before cut-off.':'Approved settlement instruction and calendar mapping available.'},
    {status:duplicate?'warn':'pass',title:'Duplicate / overlap control',detail:duplicate?'Similar live order exists for the same portfolio, security and side; reviewer confirmation required.':'No competing live order detected.'}
  ];
  if($('#pretradeChecks'))$('#pretradeChecks').innerHTML=checks.map(c=>`<div class="check-item ${c.status}"><span class="check-status">${c.status==='pass'?'✓':c.status==='warn'?'!':'×'}</span><div><strong>${c.title}</strong><small>${c.detail}</small></div><em>${c.status==='pass'?'Pass':c.status==='warn'?'Review':'Block'}</em></div>`).join('');
  const pass=checks.filter(c=>c.status==='pass').length, warn=checks.filter(c=>c.status==='warn').length, fail=checks.filter(c=>c.status==='fail').length;
  if($('#pretradeSummary'))$('#pretradeSummary').textContent=`${pass} passed${warn?` · ${warn} review`:''}${fail?` · ${fail} blocked`:''}`;
  if($('#pretradeTime'))$('#pretradeTime').textContent=`Checked ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;
  if($('#orderSubmissionState'))$('#orderSubmissionState').textContent=fail?'Submission blocked by hard control':warn?'Ready with reviewer attention':'Ready for controlled submission';
  return {fail,warn,issuer,equity,consideration,participation,cashAfter,ccy};
}
