function applyRBAC(notify=false){
  const perms=rolePermissions[state.role]||[];
  $$('[data-permission]').forEach(el=>el.classList.toggle('hidden-by-rbac',!perms.includes(el.dataset.permission)));
  $$('[data-permission-action]').forEach(el=>{
    let allowed=perms.includes(el.dataset.permissionAction);
    if(el.dataset.action==='send-broker-email'){const selected=orders.find(x=>x.id===state.currentOrder);allowed=allowed&&Boolean(selected&&selected.status==='Approved');}
    el.classList.toggle('disabled-by-rbac',!allowed); el.disabled=!allowed; el.title=allowed?'':(el.dataset.action==='send-broker-email'?'Requires an Approved order and dealer-routing authority':`Not permitted for ${roleLabels[state.role]}`);
  });
  $('#roleLabel').textContent=roleLabels[state.role];
  if(!perms.includes(permissionForPage(state.currentPage))){
    const first=$$('.nav-item:not(.hidden-by-rbac)')[0]; if(first) navigate(first.dataset.page);
  }
  if(notify) toast('Role context changed',`Interface now reflects ${roleLabels[state.role]} permissions.`);
}

function permissionForPage(page){if(page==='detail')page=state.layerParent||'command';return ({command:'dashboard.view',portfolios:'portfolio.view','private-markets':'portfolio.view','portfolio-lab':'portfolio.view',orders:'orders.view',research:'research.view',risk:'risk.view',performance:'reports.view',clients:'clients.view','investor-services':'clients.view',onboarding:'onboarding.view',ibor:'portfolio.view',financing:'risk.view',cash:'cash.view',reports:'reports.view',vault:'documents.view',operations:'operations.view',reconciliations:'operations.view','corporate-actions':'operations.view',valuation:'valuation.view',accounting:'valuation.view',regulatory:'reports.view',data:'operations.view','model-governance':'risk.view',copilot:'dashboard.view',rbac:'admin.rbac',settings:'admin.settings',audit:'audit.view'})[page]}

function navigate(page){
  const perm=permissionForPage(page); if(perm&&!hasPermission(perm)){toast('Access restricted',`${roleLabels[state.role]} does not have permission to open this workspace.`,'error');return;}
  state.currentPage=page;
  $$('.page').forEach(p=>p.classList.toggle('active',p.dataset.page===page));
  $$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));
  requestAnimationFrame(normalizeSvgChartLabels);
  window.scrollTo({top:0,behavior:'smooth'});
  $('#sidebar').classList.remove('mobile-open');
}

