function decimalMinor(value){
  const raw=String(value??'').replace(/,/g,'').trim();
  if(!/^[-+]?\d+(\.\d{0,2})?$/.test(raw))throw new Error('Use a decimal amount with up to 2 places.');
  const neg=raw.startsWith('-'); const clean=raw.replace(/^[-+]/,''); const [w,f='']=clean.split('.');
  const cents=BigInt(w)*100n+BigInt((f+'00').slice(0,2)); return neg?-cents:cents;
}
function minorDisplay(v){ const n=typeof v==='bigint'?v:BigInt(v); const sign=n<0n?'-':''; const a=n<0n?-n:n; return `${sign}${a/100n}.${String(a%100n).padStart(2,'0')}`; }

