  openDrawer({eyebrow:'CLIENT CASH ACCOUNT',title:`${a.id} · ${a.masked}`,subtitle:`${a.client} · ${a.portfolio} · ${a.currency}`,body:`<div class="drawer-summary"><div><span>Posted settled</span><strong>${a.currency} ${a.posted}</strong><small>Derived from posted ledger</small></div><div><span>Available trading</span><strong>${a.currency} ${a.available}</strong><small>After reservations / holds</small></div><div><span>Reconciliation</span><strong>${a.recon}</strong><small>Last statement ${a.statement}</small></div></div><section class="detail-section"><h3>Ownership & mapping</h3><div class="detail-grid"><div class="detail-field"><span>Legal entity</span><strong>${a.legalEntity}</strong></div><div class="detail-field"><span>Client / vehicle</span><strong>${a.client}</strong></div><div class="detail-field"><span>Mandate</span><strong>${a.mandate}</strong></div><div class="detail-field"><span>Portfolio</span><strong>${a.portfolio}</strong></div><div class="detail-field"><span>Ownership model</span><strong>${a.ownership}</strong></div><div class="detail-field"><span>Money classification</span><strong>${a.moneyClass}</strong></div><div class="detail-field"><span>Account type</span><strong>${a.type}</strong></div><div class="detail-field"><span>Provider</span><strong>${a.provider}</strong></div><div class="detail-field"><span>Identifier</span><strong>${a.masked}</strong></div><div class="detail-field"><span>Currency</span><strong>${a.currency}</strong></div><div class="detail-field"><span>Effective from</span><strong>${a.effective}</strong></div><div class="detail-field"><span>Calendar / timezone</span><strong>${a.calendar}</strong></div><div class="detail-field"><span>Tolerance policy</span><strong>${a.tolerance}</strong></div><div class="detail-field"><span>GL mapping</span><strong>${a.gl}</strong></div></div></section><section class="detail-section"><h3>Cash states</h3><div class="cash-state-mini"><div><span>Reserved</span><b>${a.currency} ${a.reserved}</b></div><div><span>Blocked</span><b>${a.currency} ${a.blocked}</b></div><div><span>Expected net</span><b>${a.currency} ${a.expected}</b></div><div><span>Withdrawable</span><b>${a.currency} ${a.withdrawable}</b></div></div><button class="text-btn" onclick="openCashExplanation('${a.id}')">Explain every component →</button></section><section class="detail-section"><h3>Lifecycle & control</h3><p><strong>${a.status}</strong> · Version ${a.version} · Maker ${a.maker}. Create, mapping change, suspension, reactivation and closure require maker-checker control.</p></section><div class="form-actions">${stateActions}</div>`});
