function cashAccountLifecycle(id,action){
  const a=cashAccounts.find(x=>x.id===id); if(!a)return;
  if(action==='approve'){
    if(!['compliance','operations','fund_accountant'].includes(state.role))return toast('Checker required','Only an authorised independent control role may approve this account.','error');
    if(a.maker==='T. Moyo')return toast('Maker-checker conflict','The maker cannot approve their own account record.','error');
    a.status='ACTIVE';a.version+=1;toast('Cash account activated',`${id} is active for controlled posting, reservation, import and reconciliation.`);
  }else if(action==='suspend'){a.status='SUSPENDED';a.version+=1;toast('Account suspended','New reservations and manual postings are blocked; corrective reconciliation remains available.','warn');}
  else if(action==='close'){
    const blockers=[]; if(decimalMinor(a.posted)!==0n)blockers.push(`Posted balance ${a.currency} ${a.posted}`); if(decimalMinor(a.reserved)!==0n)blockers.push(`Active reservations ${a.currency} ${a.reserved}`); if(a.recon.includes('Break')||a.recon.includes('blocker'))blockers.push(`Reconciliation: ${a.recon}`);
    if(blockers.length)return openControlDrawer('Account closure blocked',id,`<section class="detail-section"><h3>Blocking conditions</h3><ul>${blockers.map(x=>`<li>${x}</li>`).join('')}</ul><p>Balances, reservations, suspense, open exceptions and unreconciled periods must clear before closure.</p></section>`);
    a.status='CLOSED';a.version+=1;toast('Account closed',`${id} is read-only; late external activity will create a controlled reopen task.`);
  }else if(action==='reject'){a.status='DRAFT';a.version+=1;toast('Account returned to maker','Checker rejection recorded with the account version.','warn');}
  else if(action==='submit'){a.status='PENDING_APPROVAL';a.version+=1;toast('Account submitted','Reviewed fields frozen and routed to an independent checker.');}
  renderCashAccounts();closeDrawer();
}

