function saveReservation(){
  try{const amt=decimalMinor($('#rsvAmount').value),available=decimalMinor('7000.00');if(amt<=0n)throw new Error('Amount must be positive.');if(amt>available)throw new Error('INSUFFICIENT_AVAILABLE_CASH — requested amount exceeds USD 7,000.00 current availability.');const id=`RSV-${800+cashReservations.length}`;cashReservations.unshift({id,source:$('#rsvSource').value,purpose:$('#rsvPurpose').value,original:minorDisplay(amt),consumed:'0.00',remaining:minorDisplay(amt),currency:'USD',required:'27 Aug',expiry:'29 Aug',status:'ACTIVE',owner:roleLabels[state.role]});renderReservations();closeDrawer();toast('Reservation active',`${id} reduces available and withdrawable cash but does not change posted ledger cash.`);}catch(e){toast('Reservation blocked',e.message,'error');}
}

function startStatementImport(){
  if(!hasPermission('cash.import'))return toast('Permission denied','This role cannot stage external cash evidence.','error');
  const input=document.createElement('input');input.type='file';input.accept='.csv,.xlsx,.xls,.txt';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const id=`IMP-260826-${21+statementImports.length}`;statementImports.unshift({id,provider:'Unmapped provider',account:'Mapping required',period:'26 Aug',lines:'—',opening:'—',movement:'—',closing:'—',checks:'Pending validation',status:'RECEIVED',file:f.name,hash:'pending',maker:'T. Moyo',checker:'—'});renderStatementImports();switchCashTab('imports');toast('External file received',`${f.name} is staged only. Validation must prove account, currency, signs, duplicate controls and statement arithmetic.`);};input.click();
}

