function toast(title,message,type=''){
  const host=$('#toastStack'); const node=document.createElement('div'); node.className=`toast ${type}`; node.innerHTML=`<strong>${title}</strong><small>${message}</small>`; host.appendChild(node); setTimeout(()=>{node.style.opacity='0';node.style.transform='translateY(8px)';setTimeout(()=>node.remove(),220)},3600);
}

