function globalSearch(q){
  if(q.length<2)return;
  const matches=[];
  portfolios.filter(x=>x.name.toLowerCase().includes(q)).slice(0,3).forEach(x=>matches.push(['Portfolio',x.name,x.aum]));
  clients.filter(x=>x.name.toLowerCase().includes(q)).slice(0,3).forEach(x=>matches.push(['Client',x.name,x.id]));
  documents.filter(x=>x.name.toLowerCase().includes(q)).slice(0,3).forEach(x=>matches.push(['Document',x.name,x.type]));
  orders.filter(x=>`${x.security} ${x.id}`.toLowerCase().includes(q)).slice(0,3).forEach(x=>matches.push(['Order',x.id,x.security]));
  openDrawer({eyebrow:'GLOBAL SEARCH',title:`Results for “${q}”`,subtitle:`${matches.length} best matches across authorised records`,body:matches.length?matches.map(m=>`<button class="exception info" style="width:100%;margin-bottom:7px"><span class="severity-dot"></span><div><strong>${m[1]}</strong><small>${m[0]} · ${m[2]}</small></div><em>Open →</em></button>`).join(''):'<section class="detail-section"><h3>No matching records</h3><p>Try a client name, security ticker, order reference or document title.</p></section>'});
}

function normalizeSvgChartLabels(){
  $$('.bi-svg-chart').forEach(svg=>{
    const box=svg.getBoundingClientRect();
    const vb=svg.viewBox?.baseVal;
    if(!vb || !box.width || !vb.width)return;
    const scale=box.width/vb.width;
    const targetScreenPx=11.5;
    const userSize=Math.max(11,Math.min(36,targetScreenPx/scale));
    svg.style.setProperty('--chart-label-size',`${userSize.toFixed(2)}px`);
  });
}

function updateClock(){
  const now=new Date();
  const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Harare',weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now);
  const get=t=>parts.find(p=>p.type===t)?.value || '';
  const t=`${get('hour')}:${get('minute')}`;
  const d=`${get('day')} ${get('month')} ${get('year')}`.toUpperCase();
  const hour=Number(get('hour')), minute=Number(get('minute'));
  const weekday=get('weekday');
  const weekdayOpen=!['Sat','Sun'].includes(weekday);
  const minutes=hour*60+minute;
  const sessionOpen=weekdayOpen && minutes>=9*60 && minutes<15*60;
  const localClock=$('#localClock'),pageClock=$('#pageClock'),todayLabel=$('#todayLabel'),marketStatus=$('#marketStatus');
  if(localClock)localClock.textContent=`${t} CAT`; if(pageClock)pageClock.textContent=`${t} CAT`; if(todayLabel)todayLabel.textContent=d;
  if(marketStatus)marketStatus.textContent=sessionOpen?'ZSE market open':'ZSE market closed';
}

