function downloadTextFile(filename,content,type='text/csv;charset=utf-8'){
  const blob=new Blob([content],{type});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a'); a.href=url; a.download=filename; a.style.display='none';
  document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),500);
}
function tableToCsv(selector){
  const table=$(selector); if(!table)return '';
  return [...table.querySelectorAll('tr')].map(row=>[...row.querySelectorAll('th,td')].map(cell=>`"${cell.innerText.replace(/"/g,'""').replace(/\s+/g,' ').trim()}"`).join(',')).join('\n');
}
function pickFile({accept='.csv,.xlsx,.xls',label='File'}){
  const input=document.createElement('input'); input.type='file'; input.accept=accept;
  input.onchange=()=>{ const f=input.files?.[0]; if(f) toast(`${label} selected`,`${f.name} is ready for validation and controlled import.`); };
  input.click();
}
function openControlDrawer(title,subtitle,body){ openDrawer({eyebrow:'CONTROL WORKSPACE',title,subtitle,body}); }

function activateOrderWorkbench(tab){
  $$('[data-order-workbench-tab]').forEach(b=>b.classList.toggle('active',b.dataset.orderWorkbenchTab===tab));
  $$('[data-order-workbench-pane]').forEach(p=>p.classList.toggle('active',p.dataset.orderWorkbenchPane===tab));
}
function toggleOrderControls(){
  const panel=$('#orderControlDetails'); const button=$('#orderControlToggle'); if(!panel||!button)return;
  panel.hidden=!panel.hidden; button.textContent=panel.hidden?'Show all controls':'Hide detailed controls';
}

