function renderIbor(){
 const body=document.getElementById('iborRows');if(!body)return;
 const q=(document.getElementById('iborSearch')?.value||'').trim().toLowerCase();
 const asset=document.getElementById('iborAssetFilter')?.value||'all';const stateF=document.getElementById('iborStateFilter')?.value||'all';
 const rows=institutionalPositions.filter(p=>(!q||`${p.ticker} ${p.name} ${p.portfolio} ${p.asset}`.toLowerCase().includes(q))&&(asset==='all'||p.asset===asset)&&(stateF==='all'||p.state===stateF));
 body.innerHTML=rows.map(p=>`<tr><td><strong>${p.ticker}</strong><small>${p.name}</small></td><td>${p.portfolio}</td><td>${p.asset}</td><td>${p.qty}</td><td>${p.settled}</td><td>${p.unsettled}</td><td>${p.local}</td><td><strong>${p.base}</strong></td><td>${p.cost}</td><td>${p.accrued}</td><td>${p.available}</td><td><span class="outline-status ${p.state==='Current'?'green':'amber'}">${p.state}</span></td><td><button class="row-action" onclick="openSecondLayer('position',{id:'${p.id}'})">Open</button></td></tr>`).join('');
 const c=document.getElementById('iborCount');if(c)c.textContent=`${rows.length} representative position${rows.length===1?'':'s'}`;
}
function openPosition360(id){const p=institutionalPositions.find(x=>x.id===id);if(!p)return;openDrawer({eyebrow:'POSITION 360 · AUTHORITATIVE IBOR RECORD',title:p.ticker,subtitle:`${p.name} · ${p.portfolio}`,variant:'360',body:`<div class="workspace-360-hero"><div><span>INVESTMENT BOOK OF RECORD</span><h2>${p.ticker}</h2><p>${p.name} · ${p.asset} · ${p.portfolio}</p></div><span class="outline-status ${p.state==='Current'?'green':'amber'}">${p.state}</span></div><div class="workspace-360-metrics"><div><span>Base market value</span><strong>${p.base}</strong><small>${p.local}</small></div><div><span>Total quantity</span><strong>${p.qty}</strong><small>${p.lot}</small></div><div><span>Settled</span><strong>${p.settled}</strong><small>Authoritative quantity</small></div><div><span>Unsettled</span><strong>${p.unsettled}</strong><small>Trade lifecycle</small></div><div><span>Available to trade</span><strong>${p.available}</strong><small>After reservations</small></div></div><section class="detail-section"><h3>Position economics</h3><div class="detail-grid compact"><div class="detail-field"><span>Reference price / yield</span><strong>${p.price}</strong></div><div class="detail-field"><span>Cost basis</span><strong>${p.cost}</strong></div><div class="detail-field"><span>Accrued income</span><strong>${p.accrued}</strong></div><div class="detail-field"><span>Source</span><strong>${p.source}</strong></div></div></section><section class="detail-section"><h3>Authoritative state</h3><p>The production position record is event-sourced from trades, settlements, corporate actions, cash movements and approved valuations. External custody evidence is reconciled rather than overwriting the investment book.</p></section><div class="form-actions"><button class="btn secondary" onclick="closeDrawer();navigate('operations')">Reconciliation evidence</button><button class="btn primary" onclick="closeDrawer();navigate('orders')">Open dealing</button></div>`});}
function runInstitutionalOptimizer(){
 const values={balanced:['13.6%','6.9%','8.7%','18 bps'],defensive:['11.9%','5.2%','6.1%','14 bps'],growth:['15.1%','7.4%','10.8%','23 bps']};
 const active=document.querySelector('[data-scenario].active')?.dataset.scenario||'balanced';const v=values[active];
 ['scenarioReturn','scenarioTe','scenarioTurnover','scenarioCost'].forEach((id,i)=>{const e=document.getElementById(id);if(e)e.textContent=v[i]});
 toast('Optimisation complete',`${active[0].toUpperCase()+active.slice(1)} scenario solved within all hard constraints. Proposed orders remain uncommitted until promoted by the portfolio manager.`);
}
function selectScenario(btn){document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',b===btn));runInstitutionalOptimizer();}
function openDataSource(name){openSecondLayer('data-source',{name});}
function initInstitutionalOS(){
 renderIbor();['iborSearch','iborAssetFilter','iborStateFilter'].forEach(id=>{const e=document.getElementById(id);if(e)e.addEventListener(id==='iborSearch'?'input':'change',renderIbor)});
 document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>selectScenario(b)));
 document.querySelectorAll('[data-source-name]').forEach(b=>b.addEventListener('click',()=>openDataSource(b.dataset.sourceName)));
}
window.openPosition360=openPosition360;
document.addEventListener('DOMContentLoaded',initInstitutionalOS);


