function layerEscape(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function layerShell({parent,eyebrow,title,subtitle,stats=[],tabs=[],actions=''}){
  const statHtml=stats.map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]||''}</small></div>`).join('');
  const tabButtons=tabs.map((t,i)=>`<button type="button" class="${i===0?'active':''}" data-layer-tab="${t.id}">${t.label}</button>`).join('');
  const panes=tabs.map((t,i)=>`<section class="layer-pane ${i===0?'active':''}" data-layer-pane="${t.id}">${t.body}</section>`).join('');
  return `<div class="layer-breadcrumb"><button type="button" data-layer-back>← ${layerEscape(parentLabel(parent))}</button><i>/</i><strong>${layerEscape(title)}</strong></div><header class="layer-head"><div class="layer-head-copy"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="layer-head-actions">${actions}</div></header>${stats.length?`<div class="layer-stat-strip">${statHtml}</div>`:''}<nav class="layer-tabs" aria-label="Workspace sections">${tabButtons}</nav><div class="layer-panes">${panes}</div>`;
}
function parentLabel(parent){return ({command:'Global Investment Office',portfolios:'Whole Portfolio','private-markets':'Private Markets','portfolio-lab':'Portfolio Construction',orders:'Order Management',research:'Research & IC',risk:'Risk & Compliance',performance:'Performance & Attribution',clients:'Clients & Accounts','investor-services':'Investor Services',onboarding:'Onboarding & KYC',ibor:'IBOR & Positions',financing:'Collateral & Financing',cash:'Cash & Ledgers',operations:'Operations Control',reconciliations:'Reconciliations','corporate-actions':'Corporate Actions',valuation:'NAV & Valuation',accounting:'Accounting & Close',regulatory:'Regulatory Reporting',data:'Data Fabric & Studio','model-governance':'Model Governance',copilot:'Investment Copilot',rbac:'RBAC & Controls'})[parent]||'Workspace';}
function layerTable(headers,rows){return `<div class="layer-table-wrap"><table class="layer-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
